"""The manufacturer's own telemetry (`7d01`) layout, one map per frame span.

GENERATED by `tools/re/gen_bigdata_map.py` -- do not edit by hand.

Unlike the status map this does NOT reduce to a single whole-word displacement: families put
the engineering block at different words entirely (`power` is w18 on the classic family and
w37 on the richest published one), which is why one hard-coded offset set could only ever
serve one family. Keying on the frame's own span is safe by measurement -- profiles sharing a
span are position-identical in this section, with zero disagreements -- and the generator
refuses to write if that stops being true.

⚠️ The classic 141-byte family is NOT here: no bundled profile publishes its span, and its
offsets are hardware-confirmed. `uss.parse_extended_status` keeps that path untouched.
"""
from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class BigdataField:
    """One published telemetry reading: where it sits, and how to scale it."""

    name: str
    word: int
    bit: int
    length: int
    k: float
    c: float
    unit: str | None

    def read(self, payload: bytes) -> int | float | None:
        """The value at this position in a telemetry payload, or None if it lies past the end."""
        off = 2 * (self.word - 1)
        if off + 2 > len(payload):
            return None
        raw = (int.from_bytes(payload[off:off + 2], "big") >> self.bit) & ((1 << self.length) - 1)
        value = raw * self.k + self.c
        return round(value, 1) if isinstance(self.k, float) and self.k != 1.0 else int(value)


